2. Create src/lib/crypto.ts:
   ```typescript
   import { randomBytes, createCipheriv, createDecipheriv, createHash } from 'crypto';
   import bcrypt from 'bcrypt';

   const BCRYPT_COST = 12;
   const AES_ALGORITHM = 'aes-256-gcm';

   export const hashPassword = (password: string): Promise<string> => bcrypt.hash(password, BCRYPT_COST);
   export const verifyPassword = (password: string, hash: string): Promise<boolean> => bcrypt.compare(password, hash);

   export const generateToken = (bytes = 32): string => randomBytes(bytes).toString('base64url');
   export const generateUUID = (): string => crypto.randomUUID();

   export const hashToken = (token: string): string => createHash('sha256').update(token).digest('hex');

   export const encrypt = (plaintext: string, key: Buffer): { ciphertext: string; iv: string; tag: string } => {
     const iv = randomBytes(16);
     const cipher = createCipheriv(AES_ALGORITHM, key, iv);
     let ciphertext = cipher.update(plaintext, 'utf8', 'base64');
     ciphertext += cipher.final('base64');
     return { ciphertext, iv: iv.toString('base64'), tag: cipher.getAuthTag().toString('base64') };
   };

   export const decrypt = (ciphertext: string, iv: string, tag: string, key: Buffer): string => {
     const decipher = createDecipheriv(AES_ALGORITHM, key, Buffer.from(iv, 'base64'));
     decipher.setAuthTag(Buffer.from(tag, 'base64'));
     let plaintext = decipher.update(ciphertext, 'base64', 'utf8');
     plaintext += decipher.final('utf8');
     return plaintext;
   };
   ```
3. Never use Math.random() for any security-related operations.
