   import { Response, Request } from 'express';
   import { config } from '../config';

   const COOKIE_NAME = 'refresh_token';
   const REFRESH_PATH = '/api/v1/auth/refresh';

   export const isWebClient = (req: Request): boolean => {
     // Same-origin requests under /api/v1 are web clients
     const origin = req.get('Origin');
     const referer = req.get('Referer');
     return origin === config.webOrigin || (referer?.startsWith(config.webOrigin) ?? false);
   };

   export const setRefreshTokenCookie = (res: Response, token: string): void => {
     res.cookie(COOKIE_NAME, token, {
       httpOnly: true,
       secure: true,
       sameSite: 'strict',
       path: REFRESH_PATH,
       maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
     });
   };

   export const clearRefreshTokenCookie = (res: Response): void => {
     res.clearCookie(COOKIE_NAME, { path: REFRESH_PATH });
   };

   export const getRefreshToken = (req: Request): string | undefined => {
     // Cookie takes precedence (web), fallback to body (mobile)
     return req.cookies?.[COOKIE_NAME] || req.body?.refreshToken;
   };
   ```

