   ```typescript
   async refresh(refreshToken: string): Promise<{ accessToken: string; refreshToken: string }> {
     const tokenHash = hashToken(refreshToken);
     const storedToken = await this.repo.findRefreshToken(tokenHash);

     if (!storedToken || storedToken.revoked_at || storedToken.expires_at < new Date()) {
       throw new AuthenticationError('INVALID_REFRESH_TOKEN');
     }

     // Check if token was already used (reuse detection)
     if (storedToken.used_at) {
       // Token reuse detected! Revoke entire family
       await this.repo.revokeFamily(storedToken.family_id);
       await this.auditService.log('auth.token.reuse_detected', { familyId: storedToken.family_id });
       throw new AuthenticationError('TOKEN_REUSE_DETECTED');
     }

     // Mark current token as used
     await this.repo.markAsUsed(storedToken.id);

     // Issue new tokens with same family
     const newRefreshToken = generateToken();
     await this.repo.createRefreshToken(storedToken.user_id, hashToken(newRefreshToken), storedToken.family_id, addDays(7));

     return { accessToken: signAccessToken(...), refreshToken: newRefreshToken };
   }
   ```

