   ```typescript
   const relay = async () => {
     while (true) {
       await prisma.$transaction(async (tx) => {
         // SKIP LOCKED prevents duplicate processing
         const events = await tx.$queryRaw`
           SELECT * FROM outbox_events 
           WHERE processed_at IS NULL 
           ORDER BY created_at 
           FOR UPDATE SKIP LOCKED 
           LIMIT 100`;

         for (const event of events) {
           const queue = getQueueForEventType(event.event_type);
           await queue.add(event.event_type, event.payload);
           await tx.outboxEvent.update({ where: { id: event.id }, data: { processed_at: new Date() } });
         }
       });
       await sleep(500); // 500ms polling interval
     }
   };
