### 1.4 Create Email Consumer (src/worker/consumers/email.consumer.ts)
```typescript
import { Worker, Job } from 'bullmq';
import { redis } from '../../lib/redis';
import { transporter } from '../../lib/email';
import { templates } from '../email/templates';
import { logger } from '../../lib/logger';

interface EmailJobData {
  template: 'password-reset' | 'critical-incident-alert' | 'token-reuse-alert';
  to: string;
  locale: 'fr' | 'en';
  data: Record<string, unknown>;
}

export const emailWorker = new Worker<EmailJobData>(
  'notify.email',
  async (job: Job<EmailJobData>) => {
    const { template, to, locale, data } = job.data;
    const tmpl = templates[template];

    await transporter.sendMail({
      from: `"Secure360" <${config.smtp.from}>`,
      to,
      subject: tmpl.subject(locale, data),
      html: tmpl.html(locale, data),
      text: tmpl.text(locale, data),
    });

    logger.info({ jobId: job.id, template, to: '[REDACTED]' }, 'email.sent');
  },
  {
    connection: redis,
    concurrency: 5,
    limiter: { max: 10, duration: 1000 }, // 10 emails/second
  }
);
```

### 1.5 Configure Retry with Exponential Backoff
Add job default options when enqueuing from outbox relay or services:
```typescript
await emailQueue.add('send', payload, {
  attempts: 5,
  backoff: {
    type: 'exponential',
    delay: 60000, // 1 min, 2 min, 4 min, 8 min, 16 min
  },
});
```

### 1.6 Dead-Letter Queue
Configure dead-letter handling in the worker:
```typescript
emailWorker.on('failed', async (job, error) => {
  if (job && job.attemptsMade >= job.opts.attempts!) {
    // Move to dead-letter set
    await redis.zadd('notify.email:dlq', Date.now(), JSON.stringify({
      jobId: job.id,
      data: job.data,
      error: error.message,
      failedAt: new Date().toISOString(),
    }));
    logger.error({ jobId: job.id, template: job.data.template }, 'email.dead_lettered');
  }
});
```

## 2. Maintenance Scheduler (BullMQ Repeatable Jobs)

### 2.1 Create Maintenance Queue and Scheduler (src/worker/maintenance/scheduler.ts)
```typescript
import { Queue, Worker } from 'bullmq';
import { redis } from '../../lib/redis';

export const maintenanceQueue = new Queue('maintenance', { connection: redis });

// Register repeatable jobs on worker startup
export const registerMaintenanceJobs = async () => {
  // SLA breach scan - every minute
  await maintenanceQueue.add('sla-breach-scan', {}, {
    repeat: { every: 60000 }, // 1 minute
    jobId: 'sla-breach-scan',
  });

  // Auto-close resolved incidents - daily at 02:00 WAT
  await maintenanceQueue.add('auto-close-resolved', {}, {
    repeat: { pattern: '0 2 * * *', tz: 'Africa/Douala' },
    jobId: 'auto-close-resolved',
  });

  // Purge expired tokens - daily at 03:00 WAT
  await maintenanceQueue.add('purge-expired-tokens', {}, {
    repeat: { pattern: '0 3 * * *', tz: 'Africa/Douala' },
    jobId: 'purge-expired-tokens',
  });

  // Purge old notifications - daily at 03:30 WAT
  await maintenanceQueue.add('purge-old-notifications', {}, {
    repeat: { pattern: '30 3 * * *', tz: 'Africa/Douala' },
    jobId: 'purge-old-notifications',
  });

  // Purge processed outbox rows - daily at 04:00 WAT
  await maintenanceQueue.add('purge-outbox', {}, {
    repeat: { pattern: '0 4 * * *', tz: 'Africa/Douala' },
    jobId: 'purge-outbox',
  });
};
```

### 2.2 SLA Breach Scanner (src/worker/maintenance/sla-breach.ts)
```typescript
// SLA targets per severity (from L2 Table 11)
const SLA_HOURS: Record<string, number> = {
  CRITICAL: 4,
  HIGH: 8,
  MODERATE: 24,
  LOW: 72,
};

export const scanSlABreaches = async () => {
  const now = new Date();

  // Find incidents in non-terminal statuses that have exceeded SLA
  const breachedIncidents = await prisma.$queryRaw<Array<{ id: string; severity: string; created_at: Date }>>`
    SELECT id, severity, created_at
    FROM incidents
    WHERE status NOT IN ('RESOLVED', 'CLOSED')
      AND sla_breached_at IS NULL
      AND created_at + (
        CASE severity
          WHEN 'CRITICAL' THEN INTERVAL '4 hours'
          WHEN 'HIGH' THEN INTERVAL '8 hours'
          WHEN 'MODERATE' THEN INTERVAL '24 hours'
          WHEN 'LOW' THEN INTERVAL '72 hours'
        END
      ) < ${now}
  `;

  for (const incident of breachedIncidents) {
    // Insert into outbox for audit and potential notification
    await prisma.outboxEvent.create({
      data: {
        event_type: 'incident.sla_breached',
        payload: {
          incidentId: incident.id,
          severity: incident.severity,
          breachedAt: now.toISOString(),
        },
      },
    });

    // Mark incident as breached
    await prisma.incident.update({
      where: { id: incident.id },
      data: { sla_breached_at: now },
    });
  }

  return breachedIncidents.length;
};
```

