### 2.4 Purge Jobs (src/worker/maintenance/purges.ts)
```typescript
export const purgeExpiredRefreshTokens = async () => {
  return prisma.refreshToken.deleteMany({
    where: {
      OR: [
        { expires_at: { lt: new Date() } },
        { revoked_at: { not: null } },
      ],
    },
  });
};

export const purgeExpiredResetTokens = async () => {
  return prisma.passwordResetToken.deleteMany({
    where: {
      OR: [
        { expires_at: { lt: new Date() } },
        { used_at: { not: null } },
      ],
    },
  });
};

export const purgeExpiredIdempotencyKeys = async () => {
  return prisma.idempotencyKey.deleteMany({
    where: { expires_at: { lt: new Date() } },
  });
};

export const purgeProcessedOutboxEvents = async () => {
  // Keep processed events for 7 days for debugging, then purge
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
  return prisma.outboxEvent.deleteMany({
    where: {
      processed_at: { not: null, lt: sevenDaysAgo },
    },
  });
};

export const purgeOldNotifications = async () => {
  const ninetyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000);
  return prisma.notification.deleteMany({
    where: { created_at: { lt: ninetyDaysAgo } },
  });
};
```

### 2.5 Maintenance Worker (src/worker/consumers/maintenance.consumer.ts)
```typescript
export const maintenanceWorker = new Worker(
  'maintenance',
  async (job) => {
    const startTime = Date.now();
    let result: unknown;

    switch (job.name) {
      case 'sla-breach-scan':
        result = await scanSlaBreaches();
        break;
      case 'auto-close-resolved':
        result = await autoCloseResolvedIncidents();
        break;
      case 'purge-expired-tokens':
        result = {
          refresh: await purgeExpiredRefreshTokens(),
          reset: await purgeExpiredResetTokens(),
        };
        break;
      case 'purge-old-notifications':
        result = await purgeOldNotifications();
        break;
      case 'purge-outbox':
        result = await purgeProcessedOutboxEvents();
        break;
      case 'purge-idempotency-keys':
        result = await purgeExpiredIdempotencyKeys();
        break;
      default:
        throw new Error(`Unknown maintenance job: ${job.name}`);
    }

    logger.info({
      job: job.name,
      duration: Date.now() - startTime,
      result,
    }, 'maintenance.completed');

    return result;
  },
  { connection: redis, concurrency: 1 }
);
```

